 toolbar.innerHTML='<label>ค้นหาชื่อหรือเลขอ้างอิง<input type="search" placeholder="พิมพ์เพื่อค้นหา"></label><label>สถานะ<select><option value="all">ทั้งหมด</option><option value="pending">รอพิจารณา</option><option value="approved">อนุมัติแล้ว</option><option value="rejected">ปฏิเสธแล้ว</option><option value="cancelled">ยกเลิกแล้ว</option></select></label>';
 root.append(toolbar);const parentCurrent=isCurrent;isCurrent=()=>parentCurrent()&&toolbar.isConnected;const search=toolbar.querySelector('input'),filter=toolbar.querySelector('select');
