   const old=new Map(items.map(item=>[item.id,item])),unique=new Map();for(const item of dataItems){const existing=old.get(item.id);unique.set(item.id,existing?Object.assign(existing,item):item)}items=[...unique.values()];next=cursor;for(const id of selected)if(!items.some(item=>item.id===id&&item.status==='pending'))selected.delete(id);
   live.textContent='อัปเดตอัตโนมัติ · ล่าสุด '+new Date().toLocaleTimeString('th-TH',{timeZone:'Asia/Bangkok'});
