  bulk.textContent='อนุมัติที่เลือก ('+selected.size+' คน)';bulk.disabled=busy||refreshing||accessLost||!selected.size;search.disabled=filter.disabled=busy||accessLost;more.hidden=!next;more.disabled=busy||refreshing||accessLost;list.replaceChildren();const table=document.createElement('table');table.className='review-table';table.innerHTML='<caption class=sr-only>รายชื่อผู้สมัครกิจกรรม</caption><thead><tr><th scope=col>เลือก</th><th scope=col>ชื่อ–นามสกุล</th><th scope=col>สถานะสมัคร</th><th scope=col>เช็คอิน</th><th scope=col>จัดการ</th></tr></thead>';const tbody=document.createElement('tbody');table.append(tbody);list.append(table);
